var CONDUTA_CONTEUDO_MODULO = "<style>\n.conduta-shell { padding: 4px; }\n.conduta-tabs { display:flex; flex-wrap:wrap; gap:6px; margin-bottom:14px; border-bottom:1px solid var(--border); padding-bottom:8px; }\n.conduta-tab-btn { border:1px solid var(--border); background:var(--card-soft); color:var(--text-strong); border-radius:999px; padding:7px 14px; font-size:12.5px; font-weight:700; cursor:pointer; }\n.conduta-tab-btn.active { background:var(--metro-blue,#0b4ea2); border-color:var(--metro-blue,#0b4ea2); color:#fff; }\n.conduta-card { background:var(--card,#fff); border:1px solid var(--border); border-radius:var(--radius-sm,8px); padding:14px 16px; margin-bottom:12px; }\n.conduta-farol-badge { display:inline-block; padding:4px 14px; border-radius:999px; color:#fff; font-weight:700; font-size:13px; }\n.conduta-kpis { display:flex; gap:10px; flex-wrap:wrap; margin-bottom:14px; }\n.conduta-kpi { flex:1 1 21%; border:1px solid var(--border); border-radius:8px; padding:10px 12px; text-align:center; background:var(--card,#fff); }\n.conduta-kpi .valor { font-size:20px; font-weight:800; color:var(--metro-blue,#0b4ea2); }\n.conduta-kpi .rotulo { font-size:10.5px; color:var(--text-muted,#6b7280); }\n.conduta-toolbar { display:flex; gap:8px; flex-wrap:wrap; align-items:center; margin-bottom:12px; }\n.conduta-toolbar select, .conduta-toolbar input { padding:7px 10px; border:1px solid var(--border); border-radius:6px; font-size:12.5px; }\n.conduta-btn { border:none; border-radius:6px; padding:8px 14px; font-size:12.5px; font-weight:700; cursor:pointer; color:#fff; background:var(--metro-blue,#0b4ea2); }\n.conduta-btn.verde { background:#059669; }\n.conduta-btn.vermelho { background:#dc2626; }\n.conduta-btn.cinza { background:#6b7280; }\ntable.conduta-tabela { border-collapse:collapse; width:100%; font-size:12px; }\ntable.conduta-tabela th, table.conduta-tabela td { border:1px solid var(--border); padding:6px 8px; text-align:left; }\ntable.conduta-tabela thead th { background:var(--card-soft); }\n.conduta-status-pill { display:inline-block; padding:2px 9px; border-radius:999px; font-size:10.5px; font-weight:700; }\n.conduta-vazio { padding:20px; text-align:center; color:var(--text-muted,#6b7280); font-size:12.5px; }\n.conduta-modal-overlay { display:none; position:fixed; inset:0; background:rgba(0,0,0,.45); z-index:900; align-items:center; justify-content:center; }\n.conduta-modal-overlay.aberto { display:flex; }\n.conduta-modal-box { background:var(--card,#fff); border-radius:10px; padding:18px 20px; width:min(460px,92vw); max-height:88vh; overflow:auto; }\n.conduta-modal-box h3 { margin:0 0 12px; font-size:15px; }\n.conduta-campo { margin-bottom:10px; }\n.conduta-campo label { display:block; font-size:11.5px; font-weight:700; margin-bottom:4px; color:var(--text-muted,#6b7280); }\n.conduta-campo select, .conduta-campo input, .conduta-campo textarea { width:100%; padding:8px 10px; border:1px solid var(--border); border-radius:6px; font-size:12.5px; box-sizing:border-box; }\n.conduta-modal-acoes { display:flex; justify-content:flex-end; gap:8px; margin-top:14px; }\n</style>\n<script>\nvar CONDUTA_ESTADO = { tab: 'farol', colegas: null, catalogo: null, eventosPos: null, distancias: null };\nvar CONDUTA_API_EM_VOO = {};\n\nfunction tplConduta_renderReal_() {\n  var container = document.getElementById('tplCondutaContainer');\n  if (!container) return;\n  container.innerHTML =\n    '<div class=\"conduta-shell\">' +\n      '<div class=\"conduta-tabs\">' +\n        tplConduta_botaoTab_('farol', 'Farol do mês') +\n        tplConduta_botaoTab_('ocorrencias', 'Ocorrências') +\n        tplConduta_botaoTab_('positivos', 'Eventos Positivos') +\n        tplConduta_botaoTab_('missoes', 'Missões') +\n        tplConduta_botaoTab_('ausencias', 'Ausências') +\n        tplConduta_botaoTab_('fechamentos', 'Fechamentos') +\n        tplConduta_botaoTab_('relatorios', 'Relatórios semanais e missões') +\n        tplConduta_botaoTab_('biblioteca', 'Manuais e documentos') +\n      '</div>' +\n      '<div id=\"condutaTabBody\"></div>' +\n    '</div>' +\n    '<div class=\"conduta-modal-overlay\" id=\"condutaModalOverlay\"><div class=\"conduta-modal-box\" id=\"condutaModalBox\"></div></div>';\n\n  tplConduta_abrirTab_(CONDUTA_ESTADO.tab);\n}\n\nfunction tplConduta_botaoTab_(id, label) {\n  var ativo = CONDUTA_ESTADO.tab === id ? ' active' : '';\n  return '<button type=\"button\" class=\"conduta-tab-btn' + ativo + '\" onclick=\"tplConduta_abrirTab_(\\'' + id + '\\')\">' + escapeHtml_(label) + '</button>';\n}\n\nfunction tplConduta_abrirTab_(id) {\n  CONDUTA_ESTADO.tab = id;\n  var ajudaAnterior=document.getElementById('condutaAjudaContextual');if(ajudaAnterior)ajudaAnterior.remove();\n  document.querySelectorAll('.conduta-tab-btn').forEach(function (b) { b.classList.remove('active'); });\n  var body = document.getElementById('condutaTabBody');\n  if (body) body.innerHTML = '<div class=\"conduta-vazio\">Carregando...</div>';\n  tplConduta_renderReal_.__semReset = true; // evita loop de reset infinito no clique\n  var botoes = document.querySelectorAll('.conduta-tab-btn');\n  botoes.forEach(function (b) { if (b.textContent && tplConduta_labelDoId_(id) === b.textContent) b.classList.add('active'); });\n\n  if (id !== 'biblioteca' && body) { var ajuda=document.createElement('div');ajuda.className='conduta-card';ajuda.innerHTML='<button type=\"button\" class=\"conduta-btn cinza\" id=\"condutaAjudaTela\">Como usar esta tela</button>';body.parentNode.insertBefore(ajuda,body);ajuda.id='condutaAjudaContextual';document.getElementById('condutaAjudaTela').onclick=function(){tplConduta_abrirMaterial_('manual_colaborador',id);}; }\n  if (id === 'biblioteca') return tplConduta_renderBiblioteca_();\n  if (id === 'farol') return tplConduta_renderFarol_();\n  if (id === 'ocorrencias') return tplConduta_renderOcorrencias_();\n  if (id === 'positivos') return tplConduta_renderPositivos_();\n  if (id === 'missoes') return tplConduta_renderMissoes_();\n  if (id === 'ausencias') return tplConduta_renderAusencias_();\n  if (id === 'fechamentos') return tplConduta_renderFechamentos_();\n  if (id === 'relatorios') return tplConduta_renderRelatoriosGerenciais_();\n}\n\nfunction tplConduta_labelDoId_(id) {\n  var mapa = { farol: 'Farol do mês', ocorrencias: 'Ocorrências', positivos: 'Eventos Positivos', missoes: 'Missões', ausencias: 'Ausências', fechamentos: 'Fechamentos', relatorios: 'Relatórios semanais e missões', biblioteca: 'Manuais e documentos' };\n  return mapa[id] || '';\n}\n\nfunction tplConduta_chamarApi_(fn, payload, onSucesso, onErro) {\n  var altera=/Registrar|Remover|Fechar|Gerar|Ativar|Desativar|Processar|Homologar|Contestar|Julgar|Recorrer|Cadastrar|ResolverDestino/.test(fn);\n  if(altera&&CONDUTA_API_EM_VOO[fn]){alert('Esta ação já está sendo processada. Aguarde a conclusão.');return;}\n  if(altera)CONDUTA_API_EM_VOO[fn]=true;\n  if(typeof SGO_iniciarCarregamento_==='function')SGO_iniciarCarregamento_(altera?'Aguarde, salvando e processando...':'Aguarde, carregando informações...');\n  function finalizar_(){if(altera)delete CONDUTA_API_EM_VOO[fn];if(typeof SGO_finalizarCarregamento_==='function')SGO_finalizarCarregamento_();}\n  google.script.run\n    .withSuccessHandler(function(r){finalizar_();if(onSucesso)onSucesso(r);})\n    .withFailureHandler(function(err){finalizar_();(onErro||function(e){alert('Erro: '+((e&&e.message)||e));})(err);})\n    .Conduta_apiDispatch({ sessionId: SESSION, fn: fn, payload: payload || {} });\n}\n\nfunction tplConduta_corFarol_(farol) {\n  if (farol === 'VERDE') return '#059669';\n  if (farol === 'AMARELO') return '#b45309';\n  return '#dc2626';\n}\n\nfunction tplConduta_competenciaAtual_() {\n  var d = new Date();\n  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');\n}\n\n// ---------------- FAROL DO MÊS ----------------\nfunction tplConduta_renderFarol_() {\n  tplConduta_chamarApi_('apiObterFarolAtual', {}, function (res) {\n    var body = document.getElementById('condutaTabBody');\n    if (!body || !res) return;\n    var html = '';\n    html += (typeof Conduta_montarFarolCardHtml_ === 'function') ? Conduta_montarFarolCardHtml_(res) : '';\n    html += '<div class=\"conduta-kpis\">';\n    html += '<div class=\"conduta-kpi\"><div class=\"valor\">' + res.ico + '</div><div class=\"rotulo\">ICO</div></div>';\n    html += '<div class=\"conduta-kpi\"><div class=\"valor\">' + res.D + '</div><div class=\"rotulo\">Demérito (D)</div></div>';\n    html += '<div class=\"conduta-kpi\"><div class=\"valor\">' + res.n + '</div><div class=\"rotulo\">Divisor (n)</div></div>';\n    html += '<div class=\"conduta-kpi\"><div class=\"valor\">' + res.competencia + '</div><div class=\"rotulo\">Competência</div></div>';\n    html += '</div>';\n    if (tplConduta_podeGerir_()) html += '<div class=\"conduta-toolbar\"><button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_abrirTab_(\\'fechamentos\\')\">Conferir competência e fechamento</button></div>';\n    body.innerHTML = html;\n  });\n}\n\nfunction tplConduta_confirmarFechar_(competencia) {\n  tplConduta_chamarApi_('apiPreviaFechamento',{competencia:competencia},function(p){\n    if(!p.podeFechar){alert('Não é possível fechar: existem prazos de defesa ou decisões pendentes, ou o mês ainda está aberto. Consulte a prévia.');return;}\n    if(!confirm('Fechar '+tplConduta_compBR_(competencia)+'? O resultado ficará congelado. A data real será mantida. '+(p.resultado.sombra?'Valores apenas simulados.':'')))return;\n    tplConduta_chamarApi_('apiFecharCompetencia',{competencia:competencia},function(r){if(!r||!r.success)return alert('Falha ao fechar.');alert('Competência fechada e histórico preservado.');tplConduta_abrirTab_('fechamentos');});\n  });\n}\n\n// ---------------- OCORRÊNCIAS ----------------\nfunction tplConduta_renderOcorrencias_() {\n  var body = document.getElementById('condutaTabBody');\n  if (!body) return;\n  body.innerHTML =\n    '<div class=\"conduta-toolbar\">' +\n      '<button type=\"button\" class=\"conduta-btn vermelho\" onclick=\"tplConduta_abrirModalRegistrarOcorrencia_()\">+ Registrar ocorrência</button>' +\n      (tplConduta_podeGerir_() ? '<button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_processarPrazos_()\">Processar prazos vencidos agora</button>' : '') +\n    '</div>' +\n    (tplConduta_podeGerir_() ? '<div id=\"condutaAutomacaoPrazos\" class=\"conduta-card\" style=\"padding:10px 12px\"><span class=\"conduta-vazio\">Verificando a automação de prazos...</span></div>' : '') +\n    '<div id=\"condutaListaOcorrencias\" class=\"conduta-vazio\">Carregando...</div>';\n\n  if (tplConduta_podeGerir_()) tplConduta_renderAutomacaoPrazos_();\n\n  tplConduta_chamarApi_('apiListarOcorrencias', {}, function (itens) {\n    var alvo = document.getElementById('condutaListaOcorrencias');\n    if (!alvo) return;\n    CONDUTA_ESTADO.ocorrencias = itens || []; // os modais leem o caso daqui\n    if (!itens || !itens.length) { alvo.innerHTML = '<div class=\"conduta-vazio\">Nenhuma ocorrência.</div>'; return; }\n    var linhas = itens.map(function (o) {\n      return '<tr><td>' + escapeHtml_(o.TIPO_CODIGO) + (o.TIPO_DESCRICAO ? '<br><span class=\"conduta-vazio\" style=\"font-size:10.5px;padding:0\">' + escapeHtml_(o.TIPO_DESCRICAO) + '</span>' : '') + '</td>' +\n        '<td>' + escapeHtml_(o.COLABORADOR_NOME || '—') + '</td>' +\n        '<td>' + escapeHtml_(tplConduta_dataBR_(o.DATA_FATO)) + '</td><td>' + escapeHtml_(tplConduta_compBR_(o.COMPETENCIA)) + '</td>' +\n        '<td><span class=\"conduta-status-pill\" style=\"background:' + tplConduta_corStatus_(o.STATUS) + ';color:#fff\">' + escapeHtml_(o.STATUS) + '</span></td>' +\n        '<td>' + escapeHtml_(o.NIVEL_APLICADO || '') + ' / ' + escapeHtml_((o.PESO_APLICADO === '' || o.PESO_APLICADO === null || o.PESO_APLICADO === undefined) ? '' : String(o.PESO_APLICADO)) + '</td>' +\n        '<td>' + tplConduta_acoesOcorrencia_(o) + '</td></tr>';\n    }).join('');\n    alvo.innerHTML = '<div style=\"overflow-x:auto\"><table class=\"conduta-tabela\"><thead><tr><th>Ocorrência</th><th>Envolvido</th><th>Data</th><th>Competência</th><th>Status</th><th>Nível/Peso</th><th>Ações</th></tr></thead><tbody>' + linhas + '</tbody></table></div>';\n  }, function (err) { var alvo = document.getElementById('condutaListaOcorrencias'); if (alvo) alvo.innerHTML = '<div class=\"conduta-vazio\">Falha ao carregar.</div>'; console.error(err); });\n}\n\n// Datas sempre em pt-BR na tela. Aceita 'YYYY-MM-DD' e também\n// 'YYYY-MM-DDTHH:mm:ss' (formato que o backend devolvia quando a célula\n// tinha virado Date no Sheets, e que aparecia cru pro usuário).\nfunction tplConduta_dataBR_(v) {\n  var s = String(v || '').trim();\n  var m = s.match(/^(\\d{4})-(\\d{2})-(\\d{2})/);\n  return m ? (m[3] + '/' + m[2] + '/' + m[1]) : s;\n}\n\nfunction tplConduta_compBR_(v) {\n  var s = String(v || '').trim();\n  var m = s.match(/^(\\d{4})-(\\d{2})/);\n  return m ? (m[2] + '/' + m[1]) : s;\n}\n\nfunction tplConduta_corStatus_(status) {\n  var s = String(status || '').toUpperCase();\n  if (s === 'FIRME') return '#dc2626';\n  if (s === 'ANULADA' || s === 'DESCARTADA' || s === 'REJEITADA') return '#6b7280';\n  if (s === 'HOMOLOGADA') return '#b45309';\n  if (s === 'CONTESTADA' || s === 'EM_RECURSO') return '#7c3aed';\n  return '#0b4ea2';\n}\n\nfunction tplConduta_acoesOcorrencia_(o) {\n  var s = String(o.STATUS || '').toUpperCase();\n  var botoes = [];\n  if (s === 'REGISTRADA') {\n    // Regra 12 do programa: quem registrou a ocorrência NÃO pode homologá-la.\n    // O servidor já bloqueava, mas a tela oferecia o botão assim mesmo e o\n    // gestor só descobria depois de clicar (foi o que o Matheus viu em\n    // 24/09). Agora o botão só aparece para quem pode, e quem não pode lê o\n    // motivo no lugar dele.\n    if (o.PODE_HOMOLOGAR) {\n      botoes.push('<button type=\"button\" class=\"conduta-btn verde\" onclick=\"tplConduta_abrirModalHomologar_(\\'' + o.ID + '\\')\">Homologar</button>');\n    } else if (o.SOU_O_FISCAL) {\n      botoes.push('<span class=\"conduta-vazio\" style=\"font-size:11px\">Você registrou — outro gestor homologa</span>');\n    } else {\n      botoes.push('<span class=\"conduta-vazio\" style=\"font-size:11px\">Aguardando homologação da gestão</span>');\n    }\n  }\n  if (s === 'HOMOLOGADA') {\n    // O prazo agora aparece SEMPRE: antes o colaborador tinha 3 dias úteis\n    // para se defender e a tela nunca dizia qual era o último dia.\n    if (o.PODE_CONTESTAR) {\n      botoes.push('<button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_abrirModalContestar_(\\'' + o.ID + '\\')\">Contestar</button>');\n      if (o.PRAZO_CONTESTACAO) botoes.push('<span class=\"conduta-vazio\" style=\"font-size:11px\">até ' + escapeHtml_(tplConduta_dataBR_(o.PRAZO_CONTESTACAO)) + '</span>');\n    } else if (o.PRAZO_CONTESTACAO_VENCIDO) {\n      botoes.push('<span class=\"conduta-vazio\" style=\"font-size:11px\">Prazo de contestação encerrado em ' + escapeHtml_(tplConduta_dataBR_(o.PRAZO_CONTESTACAO)) + '</span>');\n    }\n  }\n  if (s === 'CONTESTADA' || s === 'EM_RECURSO') {\n    if (o.PODE_JULGAR) {\n      botoes.push('<button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_abrirModalJulgar_(\\'' + o.ID + '\\')\">Julgar</button>');\n    } else if (o.SOU_O_FISCAL) {\n      botoes.push('<span class=\"conduta-vazio\" style=\"font-size:11px\">Você registrou — outro gestor julga</span>');\n    } else {\n      botoes.push('<span class=\"conduta-vazio\" style=\"font-size:11px\">Em julgamento pela gestão</span>');\n    }\n  }\n  if (s === 'FIRME') {\n    if (o.PODE_RECORRER) {\n      botoes.push('<button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_abrirModalRecorrer_(\\'' + o.ID + '\\')\">Recorrer</button>');\n      if (o.PRAZO_RECURSO) botoes.push('<span class=\"conduta-vazio\" style=\"font-size:11px\">até ' + escapeHtml_(tplConduta_dataBR_(o.PRAZO_RECURSO)) + '</span>');\n    } else if (o.PRAZO_RECURSO_VENCIDO) {\n      botoes.push('<span class=\"conduta-vazio\" style=\"font-size:11px\">Prazo de recurso encerrado em ' + escapeHtml_(tplConduta_dataBR_(o.PRAZO_RECURSO)) + '</span>');\n    }\n  }\n  return botoes.join(' ') || '—';\n}\n\n// Perfis que a API trata como gestão (mesmo conjunto do isAdminSession do\n// servidor). Serve só para a tela não OFERECER o que o servidor vai recusar —\n// a autorização de verdade continua sendo a do backend.\nfunction tplConduta_podeGerir_() {\n  try {\n    var p = String((typeof USER_CONTEXT !== 'undefined' && USER_CONTEXT && USER_CONTEXT.perfil) || '').toUpperCase();\n    return p === 'ADMIN' || p === 'DIRETORIA' || p === 'GESTOR';\n  } catch (e) { return false; }\n}\n\n// A checagem diária é o que faz uma ocorrência homologada virar FIRME sozinha\n// quando o prazo de contestação passa — e FIRME é o único status que conta no\n// demérito. As APIs existiam desde sempre, mas NENHUMA tela as chamava: só\n// dava para ligar rodando a função por dentro do editor do Apps Script, o que\n// nunca foi feito. Enquanto isso, o programa inteiro contava zero.\nfunction tplConduta_renderAutomacaoPrazos_() {\n  var alvo = document.getElementById('condutaAutomacaoPrazos');\n  if (!alvo) return;\n  tplConduta_chamarApi_('apiStatusChecagemDiariaPrazos', {}, function (res) {\n    var ativo = !!(res && res.ativo);\n    alvo.innerHTML =\n      '<b>Automação de prazos:</b> ' +\n      (ativo\n        ? '<span style=\"color:#059669;font-weight:700\">LIGADA</span> — todo dia às 6h o sistema aplica os prazos vencidos sozinho.'\n        : '<span style=\"color:#dc2626;font-weight:700\">DESLIGADA</span> — nenhuma ocorrência vira FIRME sozinha, e o demérito do mês fica zerado até alguém processar os prazos na mão.') +\n      ' <button type=\"button\" class=\"conduta-btn ' + (ativo ? 'cinza' : 'verde') + '\" style=\"margin-left:8px\" onclick=\"tplConduta_alternarAutomacaoPrazos_(' + (ativo ? 'false' : 'true') + ')\">' +\n      (ativo ? 'Desligar' : 'Ligar agora') + '</button>';\n  }, function () {\n    alvo.innerHTML = '<span class=\"conduta-vazio\">Não foi possível verificar a automação de prazos.</span>';\n  });\n}\n\nfunction tplConduta_alternarAutomacaoPrazos_(ligar) {\n  if (!ligar && !confirm('Desligar a automação? Sem ela, nenhuma ocorrência vira FIRME sozinha e o demérito do mês para de ser contado até alguém processar os prazos manualmente.')) return;\n  tplConduta_chamarApi_(ligar ? 'apiAtivarChecagemDiariaPrazos' : 'apiDesativarChecagemDiariaPrazos', {}, function () {\n    alert(ligar ? 'Automação ligada — roda todo dia às 6h.' : 'Automação desligada.');\n    tplConduta_renderAutomacaoPrazos_();\n  });\n}\n\nfunction tplConduta_processarPrazos_() {\n  // Este botão converte pendências em FIRME (o único status que conta no\n  // demérito) e encerra o direito de contestação de quem ainda estava no\n  // prazo. Era o único botão destrutivo do módulo sem confirmação.\n  if (!confirm('Isto vai aplicar TODOS os prazos vencidos de uma vez: ocorrências homologadas viram FIRMES (passam a contar no demérito) e registros sem homologação são descartados. Não há como desfazer. Continuar?')) return;\n  tplConduta_chamarApi_('apiProcessarPrazosVencidosAgora', {}, function (res) {\n    alert((res && res.processadas) + ' ocorrência(s) processada(s) por prazo vencido.');\n    tplConduta_renderOcorrencias_();\n  });\n}\n\n// ---- modal genérico ----\nfunction tplConduta_abrirModal_(titulo, corpoHtml) {\n  var overlay = document.getElementById('condutaModalOverlay');\n  var box = document.getElementById('condutaModalBox');\n  if (!overlay || !box) return;\n  box.innerHTML = '<h3>' + escapeHtml_(titulo) + '</h3>' + corpoHtml;\n  overlay.classList.add('aberto');\n}\nfunction tplConduta_fecharModal_() {\n  var overlay = document.getElementById('condutaModalOverlay');\n  if (overlay) overlay.classList.remove('aberto');\n}\n\nfunction tplConduta_carregarListasBase_(callback) {\n  if (CONDUTA_ESTADO.colegas && CONDUTA_ESTADO.catalogo && CONDUTA_ESTADO.eventosPos && CONDUTA_ESTADO.distancias) { callback(); return; }\n  var pendentes = 4;\n  function pronto() { pendentes--; if (pendentes === 0) callback(); }\n  tplConduta_chamarApi_('apiListarColegas', {}, function (r) { CONDUTA_ESTADO.colegas = r || []; pronto(); });\n  tplConduta_chamarApi_('apiListarCatalogoOcorrencias', {}, function (r) { CONDUTA_ESTADO.catalogo = r || []; pronto(); });\n  tplConduta_chamarApi_('apiListarEventosPositivosTipo', {}, function (r) { CONDUTA_ESTADO.eventosPos = r || []; pronto(); });\n  tplConduta_chamarApi_('apiListarDistancias', {}, function (r) { CONDUTA_ESTADO.distancias = r || []; pronto(); });\n}\n\nfunction tplConduta_optionsColegas_() {\n  return '<option value=\"\">Selecione...</option>' + (CONDUTA_ESTADO.colegas || []).map(function (c) {\n    return '<option value=\"' + escapeHtml_(c.ID) + '\">' + escapeHtml_(c.NOME) + '</option>';\n  }).join('');\n}\nfunction tplConduta_optionsCatalogo_() {\n  var porGrupo = {};\n  (CONDUTA_ESTADO.catalogo || []).forEach(function (t) { (porGrupo[t.GRUPO] = porGrupo[t.GRUPO] || []).push(t); });\n  return '<option value=\"\">Selecione...</option>' + Object.keys(porGrupo).sort().map(function (g) {\n    return '<optgroup label=\"' + escapeHtml_(g) + '\">' + porGrupo[g].map(function (t) {\n      return '<option value=\"' + escapeHtml_(t.CODIGO) + '\">' + escapeHtml_(t.CODIGO) + ' — ' + escapeHtml_(t.DESCRICAO) + '</option>';\n    }).join('') + '</optgroup>';\n  }).join('');\n}\nfunction tplConduta_optionsEventosPositivos_() {\n  return '<option value=\"\">Selecione...</option>' + (CONDUTA_ESTADO.eventosPos || []).map(function (t) {\n    return '<option value=\"' + escapeHtml_(t.CODIGO) + '\">' + escapeHtml_(t.DESCRICAO) + '</option>';\n  }).join('');\n}\nfunction tplConduta_optionsDistancias_() {\n  return '<option value=\"\">Selecione...</option>' + (CONDUTA_ESTADO.distancias || []).map(function (d) {\n    return '<option value=\"' + escapeHtml_(d.ID) + '\">' + escapeHtml_(d.DESTINO) + (d.CNPJ?' — CNPJ '+escapeHtml_(d.CNPJ):'') + ' (' + d.KM_TRECHO + 'km' + (d.QUALIFICA ? ', qualifica' : '') + ')</option>';\n  }).join('');\n}\nfunction tplConduta_dataHoje_() {\n  var d = new Date();\n  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');\n}\n\nfunction tplConduta_abrirModalRegistrarOcorrencia_() {\n  tplConduta_carregarListasBase_(function () {\n    tplConduta_abrirModal_('Registrar ocorrência',\n      '<div class=\"conduta-campo\"><label>Colaborador envolvido *</label><select id=\"cnd_reg_colaborador\">' + tplConduta_optionsColegas_() + '</select></div>' +\n      '<div class=\"conduta-campo\"><label>Tipo *</label><select id=\"cnd_reg_tipo\">' + tplConduta_optionsCatalogo_() + '</select></div>' +\n      '<div class=\"conduta-campo\"><label>Data do fato *</label><input type=\"date\" id=\"cnd_reg_data\" value=\"' + tplConduta_dataHoje_() + '\"></div>' +\n      '<div class=\"conduta-campo\"><label>Foto (opcional)</label><input type=\"file\" accept=\"image/*\" id=\"cnd_reg_foto\" onchange=\"tplConduta_preverFoto_(this,\\'cnd_reg_foto_preview\\')\">' +\n      '<div id=\"cnd_reg_foto_preview\" style=\"margin-top:8px\"></div></div>' +\n      '<div class=\"conduta-campo\"><label>Legenda da foto</label><input type=\"text\" id=\"cnd_reg_foto_legenda\" placeholder=\"Descreva o que a foto mostra\"></div>' +\n      '<div class=\"conduta-modal-acoes\"><button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button>' +\n      '<button type=\"button\" class=\"conduta-btn vermelho\" id=\"cnd_reg_btn_salvar\" onclick=\"tplConduta_salvarRegistrarOcorrencia_()\">Registrar</button></div>');\n  });\n}\n\nfunction tplConduta_preverFoto_(inputEl, previewId) {\n  var preview = document.getElementById(previewId);\n  if (!preview) return;\n  var arquivo = inputEl && inputEl.files && inputEl.files[0];\n  if (!arquivo) { preview.innerHTML = ''; return; }\n  var reader = new FileReader();\n  reader.onload = function (e) {\n    preview.innerHTML = '<img src=\"' + e.target.result + '\" style=\"max-width:100%;max-height:180px;border-radius:8px;border:1px solid var(--border,#3a4657)\">';\n  };\n  reader.readAsDataURL(arquivo);\n}\n\nfunction tplConduta_salvarRegistrarOcorrencia_() {\n  var payload = {\n    colaboradorId: getValue_('cnd_reg_colaborador'), tipoCodigo: getValue_('cnd_reg_tipo'),\n    dataFato: getValue_('cnd_reg_data'), fotoLegenda: getValue_('cnd_reg_foto_legenda')\n  };\n  if (!payload.colaboradorId || !payload.tipoCodigo || !payload.dataFato) return alert('Preencha todos os campos.');\n\n  function prosseguir() {\n    tplConduta_chamarApi_('apiRegistrarOcorrencia', payload, function (res) {\n      if (!res || !res.success) return alert((res && res.message) || 'Erro ao registrar.');\n      tplConduta_fecharModal_();\n      tplConduta_renderOcorrencias_();\n    });\n  }\n\n  var fotoInput = document.getElementById('cnd_reg_foto');\n  var arquivo = fotoInput && fotoInput.files && fotoInput.files[0];\n  if (!arquivo) { prosseguir(); return; }\n\n  var btn = document.getElementById('cnd_reg_btn_salvar');\n  if (btn) { btn.disabled = true; btn.textContent = 'Enviando foto...'; }\n\n  // CORREÇÃO 2026-09-24: frotaComprimirImagem_ NUNCA rejeita -- devolve null\n  // quando o arquivo é HEIC, está corrompido ou o canvas falha. Antes o código\n  // seguia direto e gravava a ocorrência SEM A FOTO, sem nenhum aviso: a\n  // evidência do fato sumia em silêncio. Também restauramos o botão em todos\n  // os caminhos, senão ele ficava travado escrito \"Enviando foto...\" e o\n  // usuário tinha que refazer o cadastro inteiro.\n  function restaurarBotao_() { if (btn) { btn.disabled = false; btn.textContent = 'Registrar'; } }\n\n  frotaComprimirImagem_(arquivo, 1280, 0.75).then(function (comprimido) {\n    if (!comprimido) {\n      restaurarBotao_();\n      if (!confirm('Não foi possível preparar esta foto (formato não suportado ou arquivo com problema). Registrar a ocorrência SEM a foto?')) return;\n      prosseguir();\n      return;\n    }\n    tplConduta_chamarApi_('apiUploadFoto', { base64: comprimido.base64, mimeType: comprimido.mimeType, nomeArquivo: comprimido.nomeArquivo }, function (resUpload) {\n      if (resUpload && resUpload.success) { payload.fotoUrl = resUpload.url; prosseguir(); return; }\n      restaurarBotao_();\n      if (!confirm('A foto não pôde ser enviada. Registrar a ocorrência SEM a foto?')) return;\n      prosseguir();\n    }, function (err) {\n      restaurarBotao_();\n      alert('Falha ao enviar a foto: ' + ((err && err.message) || err) + ' — a ocorrência NÃO foi registrada, tente de novo.');\n    });\n  });\n}\n\n// Bloco de contexto do caso: quem, o quê, quem registrou, foto e — quando já\n// houve defesa — o texto da contestação e do recurso. Antes disso, homologar e\n// julgar eram decisões tomadas com um código de 6 letras na tela.\nfunction tplConduta_detalheOcorrenciaHtml_(id, comDefesa) {\n  var lista = CONDUTA_ESTADO.ocorrencias || [];\n  var o = null;\n  for (var i = 0; i < lista.length; i++) { if (String(lista[i].ID) === String(id)) { o = lista[i]; break; } }\n  if (!o) return '<div class=\"conduta-vazio\">Não foi possível carregar o detalhe — recarregue a lista.</div>';\n\n  var h = '<div class=\"conduta-card\" style=\"margin-bottom:12px\">';\n  h += '<div><b>Envolvido:</b> ' + escapeHtml_(o.COLABORADOR_NOME || '—') + '</div>';\n  h += '<div><b>Ocorrência:</b> ' + escapeHtml_(o.TIPO_CODIGO || '') + (o.TIPO_DESCRICAO ? ' — ' + escapeHtml_(o.TIPO_DESCRICAO) : '') + '</div>';\n  h += '<div><b>Nível/Peso:</b> ' + escapeHtml_(o.NIVEL_APLICADO || '—') + ' / ' + escapeHtml_(String(o.PESO_APLICADO === undefined || o.PESO_APLICADO === '' ? '—' : o.PESO_APLICADO)) + '</div>';\n  h += '<div><b>Data do fato:</b> ' + escapeHtml_(tplConduta_dataBR_(o.DATA_FATO)) + '</div>';\n  h += '<div><b>Registrada por:</b> ' + escapeHtml_(o.FISCAL_NOME || '—') + '</div>';\n  if (o.FOTO_URL) {\n    h += '<div style=\"margin-top:6px\"><b>Evidência:</b> <a href=\"' + escapeHtml_(o.FOTO_URL) + '\" target=\"_blank\" rel=\"noopener\">abrir foto</a>';\n    if (o.FOTO_LEGENDA) h += ' <span class=\"conduta-vazio\" style=\"font-size:11px\">(' + escapeHtml_(o.FOTO_LEGENDA) + ')</span>';\n    h += '</div>';\n  } else {\n    h += '<div style=\"margin-top:6px\" class=\"conduta-vazio\" style=\"font-size:11px\">Sem foto anexada.</div>';\n  }\n  if (comDefesa) {\n    h += '<hr style=\"border:none;border-top:1px solid var(--border);margin:10px 0\">';\n    h += '<div><b>Contestação do colaborador:</b><br>' + (o.TEXTO_CONTESTACAO ? escapeHtml_(o.TEXTO_CONTESTACAO) : '<span class=\"conduta-vazio\">(sem texto registrado)</span>') + '</div>';\n    if (o.TEXTO_RECURSO) h += '<div style=\"margin-top:8px\"><b>Recurso:</b><br>' + escapeHtml_(o.TEXTO_RECURSO) + '</div>';\n  }\n  h += '</div>';\n  return h;\n}\n\nfunction tplConduta_abrirModalHomologar_(id) {\n  tplConduta_abrirModal_('Homologar ocorrência',\n    tplConduta_detalheOcorrenciaHtml_(id, false) +\n    '<div class=\"conduta-campo\"><label>Justificativa (se rejeitar)</label><textarea id=\"cnd_hom_texto\" rows=\"3\"></textarea></div>' +\n    '<div class=\"conduta-modal-acoes\"><button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button>' +\n    '<button type=\"button\" class=\"conduta-btn vermelho\" onclick=\"tplConduta_salvarHomologar_(\\'' + id + '\\',\\'REJEITAR\\')\">Rejeitar</button>' +\n    '<button type=\"button\" class=\"conduta-btn verde\" onclick=\"tplConduta_salvarHomologar_(\\'' + id + '\\',\\'APROVAR\\')\">Aprovar</button></div>');\n}\nfunction tplConduta_salvarHomologar_(id, decisao) {\n  tplConduta_chamarApi_('apiHomologarOcorrencia', { id: id, decisao: decisao, justificativa: getValue_('cnd_hom_texto') }, function (res) {\n    if (!res || !res.success) return alert((res && res.message) || 'Erro.');\n    tplConduta_fecharModal_();\n    tplConduta_renderOcorrencias_();\n  });\n}\n\nfunction tplConduta_abrirModalContestar_(id) {\n  tplConduta_abrirModal_('Contestar ocorrência',\n    '<div class=\"conduta-campo\"><label>Motivo da contestação *</label><textarea id=\"cnd_con_texto\" rows=\"4\"></textarea></div>' +\n    '<div class=\"conduta-modal-acoes\"><button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button>' +\n    '<button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_salvarContestar_(\\'' + id + '\\')\">Enviar contestação</button></div>');\n}\nfunction tplConduta_salvarContestar_(id) {\n  var texto = getValue_('cnd_con_texto');\n  if (!texto) return alert('Descreva o motivo.');\n  tplConduta_chamarApi_('apiContestarOcorrencia', { id: id, texto: texto }, function (res) {\n    if (!res || !res.success) return alert((res && res.message) || 'Erro.');\n    tplConduta_fecharModal_();\n    tplConduta_renderOcorrencias_();\n  });\n}\n\nfunction tplConduta_abrirModalJulgar_(id) {\n  tplConduta_abrirModal_('Julgar ocorrência',\n    tplConduta_detalheOcorrenciaHtml_(id, true) +\n    '<div class=\"conduta-campo\"><label>Fundamentação</label><textarea id=\"cnd_jul_texto\" rows=\"4\"></textarea></div>' +\n    '<div class=\"conduta-modal-acoes\"><button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button>' +\n    '<button type=\"button\" class=\"conduta-btn verde\" onclick=\"tplConduta_salvarJulgar_(\\'' + id + '\\',\\'ANULAR\\')\">Anular</button>' +\n    '<button type=\"button\" class=\"conduta-btn vermelho\" onclick=\"tplConduta_salvarJulgar_(\\'' + id + '\\',\\'MANTER\\')\">Manter (firme)</button></div>');\n}\nfunction tplConduta_salvarJulgar_(id, decisao) {\n  tplConduta_chamarApi_('apiJulgarOcorrencia', { id: id, decisao: decisao, textoJulgamento: getValue_('cnd_jul_texto') }, function (res) {\n    if (!res || !res.success) return alert((res && res.message) || 'Erro.');\n    tplConduta_fecharModal_();\n    tplConduta_renderOcorrencias_();\n  });\n}\n\nfunction tplConduta_abrirModalRecorrer_(id) {\n  tplConduta_abrirModal_('Recorrer de ocorrência firme',\n    '<div class=\"conduta-campo\"><label>Motivo do recurso *</label><textarea id=\"cnd_rec_texto\" rows=\"4\"></textarea></div>' +\n    '<div class=\"conduta-modal-acoes\"><button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button>' +\n    '<button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_salvarRecorrer_(\\'' + id + '\\')\">Enviar recurso</button></div>');\n}\nfunction tplConduta_salvarRecorrer_(id) {\n  var texto = getValue_('cnd_rec_texto');\n  if (!texto) return alert('Descreva o motivo.');\n  tplConduta_chamarApi_('apiRecorrerOcorrencia', { id: id, texto: texto }, function (res) {\n    if (!res || !res.success) return alert((res && res.message) || 'Erro.');\n    tplConduta_fecharModal_();\n    tplConduta_renderOcorrencias_();\n  });\n}\n\n// ---------------- EVENTOS POSITIVOS ----------------\nfunction tplConduta_renderPositivos_() {\n  var body=document.getElementById('condutaTabBody');if(!body)return;\n  body.innerHTML='<div class=\"conduta-toolbar\"><button type=\"button\" class=\"conduta-btn verde\" onclick=\"tplConduta_abrirModalRegistrarPositivo_()\">+ Reconhecer pessoa, grupo ou departamento</button></div><div id=\"condutaListaPositivos\" class=\"conduta-vazio\">Carregando...</div>';\n  tplConduta_carregarListasBase_(function(){tplConduta_chamarApi_('apiListarEventosPositivos',{},function(itens){var alvo=document.getElementById('condutaListaPositivos');if(!alvo)return;if(!itens||!itens.length){alvo.innerHTML='<div class=\"conduta-vazio\">Nenhum reconhecimento registrado ainda.</div>';return;}var mapa={};(CONDUTA_ESTADO.colegas||[]).forEach(function(c){mapa[c.ID]=c.NOME;});var linhas=itens.map(function(e){var nome=e.TIPO_ALVO==='GRUPO'?(e.GRUPO_NOME||'Grupo/Departamento'):(mapa[e.COLABORADOR_ID]||e.COLABORADOR_ID||'Colega');return '<tr><td>'+escapeHtml_(nome)+'</td><td>'+escapeHtml_(e.TIPO_CODIGO)+'</td><td>'+escapeHtml_(e.TEXTO_RECONHECIMENTO||'')+'</td><td>'+escapeHtml_(tplConduta_dataBR_(e.DATA_FATO))+'</td></tr>';}).join('');alvo.innerHTML='<p class=\"conduta-vazio\">Os elogios são compartilhados com toda a equipe. Cobranças e ocorrências ficam restritas ao responsável, ao fiscal e à gestão.</p><table class=\"conduta-tabela\"><thead><tr><th>Reconhecido(s)</th><th>Motivo</th><th>Melhoria observada</th><th>Data</th></tr></thead><tbody>'+linhas+'</tbody></table>';});});\n}\nfunction tplConduta_abrirModalRegistrarPositivo_(){tplConduta_carregarListasBase_(function(){tplConduta_abrirModal_('Reconhecer pessoa, grupo ou departamento','<div class=\"conduta-campo\"><label>Reconhecer *</label><select id=\"cnd_pos_alvo\" onchange=\"tplConduta_alternarAlvoPositivo_()\"><option value=\"INDIVIDUAL\">Uma pessoa</option><option value=\"GRUPO\">Grupo ou departamento</option></select></div><div class=\"conduta-campo\" id=\"cnd_pos_individual\"><label>Colega *</label><select id=\"cnd_pos_colaborador\">'+tplConduta_optionsColegas_()+'</select></div><div id=\"cnd_pos_grupo\" style=\"display:none\"><div class=\"conduta-campo\"><label>Nome do grupo/departamento *</label><input id=\"cnd_pos_grupo_nome\" placeholder=\"Ex.: Metrologia, Equipe de Campo\"></div><div class=\"conduta-campo\"><label>Pessoas que receberão o elogio *</label><select id=\"cnd_pos_destinatarios\" multiple size=\"6\">'+tplConduta_optionsColegas_().replace('<option value=\"\">Selecione...</option>','')+'</select><small>Use Ctrl para selecionar várias pessoas.</small></div></div><div class=\"conduta-campo\"><label>Motivo *</label><select id=\"cnd_pos_tipo\">'+tplConduta_optionsEventosPositivos_()+'</select></div><div class=\"conduta-campo\"><label>O que foi visto de melhoria? *</label><textarea id=\"cnd_pos_texto\" rows=\"4\"></textarea></div><div class=\"conduta-campo\"><label>Data *</label><input type=\"date\" id=\"cnd_pos_data\" value=\"'+tplConduta_dataHoje_()+'\"></div><div class=\"conduta-modal-acoes\"><button class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button><button class=\"conduta-btn verde\" onclick=\"tplConduta_salvarRegistrarPositivo_()\">Reconhecer</button></div>');});}\nfunction tplConduta_alternarAlvoPositivo_(){var g=getValue_('cnd_pos_alvo')==='GRUPO';document.getElementById('cnd_pos_individual').style.display=g?'none':'';document.getElementById('cnd_pos_grupo').style.display=g?'':'none';}\nfunction tplConduta_salvarRegistrarPositivo_(){var t=getValue_('cnd_pos_alvo')||'INDIVIDUAL',el=document.getElementById('cnd_pos_destinatarios');var p={tipoAlvo:t,colaboradorId:getValue_('cnd_pos_colaborador'),grupoNome:getValue_('cnd_pos_grupo_nome'),destinatarios:el?Array.from(el.selectedOptions).map(function(o){return o.value;}):[],texto:getValue_('cnd_pos_texto'),tipoCodigo:getValue_('cnd_pos_tipo'),dataFato:getValue_('cnd_pos_data')};if(!p.tipoCodigo||!p.dataFato||!p.texto||(t==='INDIVIDUAL'&&!p.colaboradorId)||(t==='GRUPO'&&(!p.grupoNome||!p.destinatarios.length)))return alert('Preencha o destinatário, o motivo e a melhoria observada.');tplConduta_chamarApi_('apiRegistrarEventoPositivo',p,function(r){if(!r||!r.success)return alert((r&&r.message)||'Erro.');tplConduta_fecharModal_();tplConduta_renderPositivos_();});}\n\n// ---------------- MISSÕES ----------------// ---------------- MISSÕES ----------------\nfunction tplConduta_renderMissoes_() {\n  var body = document.getElementById('condutaTabBody');\n  if (!body) return;\n  body.innerHTML =\n    '<div class=\"conduta-toolbar\"><button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_abrirModalRegistrarMissao_()\">+ Registrar missão</button><button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_abrirModalCadastrarDestino_()\">+ Cadastrar cidade/destino</button></div>' +\n    '<div id=\"condutaListaMissoes\" class=\"conduta-vazio\">Carregando...</div>';\n\n  tplConduta_chamarApi_('apiListarMissoes', {}, function (itens) {\n    var alvo = document.getElementById('condutaListaMissoes');\n    if (!alvo) return;\n    if (!itens || !itens.length) { alvo.innerHTML = '<div class=\"conduta-vazio\">Nenhuma missão registrada ainda.</div>'; return; }\n    var mapaColegas = {};\n    (CONDUTA_ESTADO.colegas || []).forEach(function (c) { mapaColegas[c.ID] = c.NOME; });\n    var linhas = itens.map(function (m) {\n      var exec2 = m.EXECUTANTE_2_ID ? (' + ' + (m.EXECUTANTE_2_NOME || mapaColegas[m.EXECUTANTE_2_ID] || 'Colaborador não localizado')) : '';\n      return '<tr><td>' + escapeHtml_(m.DESTINO) + ' (' + m.KM_TRECHO + 'km)</td><td>' + escapeHtml_(tplConduta_dataBR_(m.DATA)) + '</td>' +\n        '<td>' + escapeHtml_(m.EXECUTANTE_1_NOME || mapaColegas[m.EXECUTANTE_1_ID] || 'Colaborador não localizado') + escapeHtml_(exec2) + '</td>' +\n        '<td>' + ((m.QUALIFICA === true || String(m.QUALIFICA).toUpperCase() === 'TRUE') ? '<span class=\"conduta-status-pill\" style=\"background:#059669;color:#fff\">QUALIFICA</span>' : '—') + '</td>' +\n        '<td>' + (tplConduta_podeGerir_() ? '<button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_removerMissao_(\\'' + m.ID + '\\')\">Remover</button>' : '—') + '</td></tr>';\n    }).join('');\n    alvo.innerHTML = '<table class=\"conduta-tabela\"><thead><tr><th>Destino</th><th>Data</th><th>Executante(s)</th><th>Qualifica</th><th></th></tr></thead><tbody>' + linhas + '</tbody></table>';\n  });\n}\nfunction tplConduta_abrirModalCadastrarDestino_(){tplConduta_abrirModal_('Cadastrar cidade ou destino','<div class=\"conduta-campo\"><label>CNPJ do cliente (opcional)</label><div class=\"conduta-toolbar\"><input id=\"cnd_dest_cnpj\" placeholder=\"Somente números\"><button class=\"conduta-btn\" onclick=\"tplConduta_resolverDestinoCnpj_()\">Buscar CNPJ</button></div></div><div class=\"conduta-campo\"><label>Cidade/UF *</label><input id=\"cnd_dest_nome\" placeholder=\"Ex.: Goiânia/GO\"></div><div class=\"conduta-campo\"><label>Distância do trecho em km *</label><input type=\"number\" min=\"0\" step=\"0.1\" id=\"cnd_dest_km\"></div><input type=\"hidden\" id=\"cnd_dest_cliente\"><input type=\"hidden\" id=\"cnd_dest_origem\" value=\"MANUAL\"><div id=\"cnd_dest_info\"></div><div class=\"conduta-modal-acoes\"><button class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button><button class=\"conduta-btn\" onclick=\"tplConduta_salvarDestino_()\">Salvar destino</button></div>');}\nfunction tplConduta_resolverDestinoCnpj_(){tplConduta_chamarApi_('apiResolverDestinoCnpj',{cnpj:getValue_('cnd_dest_cnpj')},function(r){document.getElementById('cnd_dest_nome').value=r.destino||'';document.getElementById('cnd_dest_cliente').value=r.clienteId||'';document.getElementById('cnd_dest_origem').value=r.origem||'API';if(r.referencia)document.getElementById('cnd_dest_km').value=r.referencia.KM_TRECHO||'';document.getElementById('cnd_dest_info').innerHTML='<div class=\"conduta-vazio\">'+escapeHtml_(r.clienteNome||'CNPJ consultado')+' — '+escapeHtml_(r.destino)+'</div>';});}\nfunction tplConduta_salvarDestino_(){var p={cnpj:getValue_('cnd_dest_cnpj'),clienteId:getValue_('cnd_dest_cliente'),destino:getValue_('cnd_dest_nome'),kmTrecho:getValue_('cnd_dest_km'),origem:getValue_('cnd_dest_origem')};if(!p.destino||p.kmTrecho==='')return alert('Informe cidade/UF e distância.');tplConduta_chamarApi_('apiCadastrarDestino',p,function(){CONDUTA_ESTADO.distancias=null;tplConduta_fecharModal_();tplConduta_renderMissoes_();});}\nfunction tplConduta_removerMissao_(id) {\n  if (!confirm('Remover esta missão?')) return;\n  tplConduta_chamarApi_('apiRemoverMissao', { id: id }, function () { tplConduta_renderMissoes_(); });\n}\nfunction tplConduta_abrirModalRegistrarMissao_() {\n  tplConduta_carregarListasBase_(function () {\n    tplConduta_abrirModal_('Registrar missão',\n      '<div class=\"conduta-campo\"><label>Destino *</label><select id=\"cnd_mis_destino\">' + tplConduta_optionsDistancias_() + '</select></div>' +\n      '<div class=\"conduta-campo\"><label>Data *</label><input type=\"date\" id=\"cnd_mis_data\" value=\"' + tplConduta_dataHoje_() + '\"></div>' +\n      '<div class=\"conduta-campo\"><label>1º executante *</label><select id=\"cnd_mis_exec1\">' + tplConduta_optionsColegas_() + '</select></div>' +\n      '<div class=\"conduta-campo\"><label>2º executante (opcional)</label><select id=\"cnd_mis_exec2\">' + tplConduta_optionsColegas_() + '</select></div>' +\n      '<div class=\"conduta-modal-acoes\"><button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button>' +\n      '<button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_salvarRegistrarMissao_()\">Registrar</button></div>');\n  });\n}\nfunction tplConduta_salvarRegistrarMissao_() {\n  var payload = {\n    referenciaId: getValue_('cnd_mis_destino'), data: getValue_('cnd_mis_data'),\n    executante1Id: getValue_('cnd_mis_exec1'), executante2Id: getValue_('cnd_mis_exec2')\n  };\n  if (!payload.referenciaId || !payload.data || !payload.executante1Id) return alert('Preencha destino, data e o 1º executante.');\n  tplConduta_chamarApi_('apiRegistrarMissao', payload, function (res) {\n    if (!res || !res.success) return alert((res && res.message) || 'Erro.');\n    tplConduta_fecharModal_();\n    tplConduta_renderMissoes_();\n  });\n}\n\n// ---------------- AUSÊNCIAS ----------------\nfunction tplConduta_renderAusencias_() {\n  var body = document.getElementById('condutaTabBody');\n  if (!body) return;\n  body.innerHTML =\n    '<div class=\"conduta-toolbar\"><button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_abrirModalRegistrarAusencia_()\">+ Registrar ausência</button></div>' +\n    '<div id=\"condutaListaAusencias\" class=\"conduta-vazio\">Carregando...</div>';\n\n  tplConduta_chamarApi_('apiListarAusencias', {}, function (itens) {\n    var alvo = document.getElementById('condutaListaAusencias');\n    if (!alvo) return;\n    if (!itens || !itens.length) { alvo.innerHTML = '<div class=\"conduta-vazio\">Nenhuma ausência registrada.</div>'; return; }\n    var mapaColegas = {};\n    (CONDUTA_ESTADO.colegas || []).forEach(function (c) { mapaColegas[c.ID] = c.NOME; });\n    var linhas = itens.map(function (a) {\n      return '<tr><td>' + escapeHtml_(mapaColegas[a.COLABORADOR_ID] || a.COLABORADOR_ID) + '</td><td>' + escapeHtml_(a.TIPO) + '</td>' +\n        '<td>' + escapeHtml_(a.DATA_INICIO) + ' a ' + escapeHtml_(a.DATA_FIM) + '</td>' +\n        '<td>' + (tplConduta_podeGerir_() ? '<button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_removerAusencia_(\\'' + a.ID + '\\')\">Remover</button>' : '—') + '</td></tr>';\n    }).join('');\n    alvo.innerHTML = '<table class=\"conduta-tabela\"><thead><tr><th>Colaborador</th><th>Tipo</th><th>Período</th><th></th></tr></thead><tbody>' + linhas + '</tbody></table>';\n  });\n}\nfunction tplConduta_removerAusencia_(id) {\n  if (!confirm('Remover esta ausência?')) return;\n  tplConduta_chamarApi_('apiRemoverAusencia', { id: id }, function () { tplConduta_renderAusencias_(); });\n}\nfunction tplConduta_abrirModalRegistrarAusencia_() {\n  tplConduta_carregarListasBase_(function () {\n    tplConduta_abrirModal_('Registrar ausência',\n      '<div class=\"conduta-campo\"><label>Colaborador *</label><select id=\"cnd_aus_colaborador\">' + tplConduta_optionsColegas_() + '</select></div>' +\n      '<div class=\"conduta-campo\"><label>Tipo *</label><select id=\"cnd_aus_tipo\"><option value=\"FERIAS\">Férias</option><option value=\"AFASTAMENTO\">Afastamento</option></select></div>' +\n      '<div class=\"conduta-campo\"><label>Data início *</label><input type=\"date\" id=\"cnd_aus_inicio\"></div>' +\n      '<div class=\"conduta-campo\"><label>Data fim *</label><input type=\"date\" id=\"cnd_aus_fim\"></div>' +\n      '<div class=\"conduta-modal-acoes\"><button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_fecharModal_()\">Cancelar</button>' +\n      '<button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_salvarRegistrarAusencia_()\">Registrar</button></div>');\n  });\n}\nfunction tplConduta_salvarRegistrarAusencia_() {\n  var payload = {\n    colaboradorId: getValue_('cnd_aus_colaborador'), tipo: getValue_('cnd_aus_tipo'),\n    dataInicio: getValue_('cnd_aus_inicio'), dataFim: getValue_('cnd_aus_fim')\n  };\n  if (!payload.colaboradorId || !payload.dataInicio || !payload.dataFim) return alert('Preencha todos os campos.');\n  tplConduta_chamarApi_('apiRegistrarAusencia', payload, function (res) {\n    if (!res || !res.success) return alert((res && res.message) || 'Erro.');\n    tplConduta_fecharModal_();\n    tplConduta_renderAusencias_();\n  });\n}\n\n// ---------------- FECHAMENTOS ----------------\nfunction tplConduta_renderFechamentos_() {\n  var body = document.getElementById('condutaTabBody');\n  if (!body) return;\n  body.innerHTML = (tplConduta_podeGerir_() ? '<div class=\"conduta-card\"><h3>Conferir mês anterior e pendências</h3><p>A competência é o mês do fato. Homologação e decisão mantêm suas datas reais. A prévia pode ser consultada enquanto há recurso; o fechamento definitivo aguarda a conclusão das defesas.</p><label for=\"condutaPreviaComp\">Competência para conferência</label><div class=\"conduta-toolbar\"><input type=\"month\" id=\"condutaPreviaComp\" value=\"'+tplConduta_competenciaAnterior_()+'\"><button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_consultarPrevia_()\">Consultar prévia</button></div><div id=\"condutaPreviaResultado\"></div></div>' : '') + '<div id=\"condutaListaFechamentos\" class=\"conduta-vazio\">Carregando...</div>';\n\n  tplConduta_chamarApi_('apiListarFechamentos', {}, function (itens) {\n    var alvo = document.getElementById('condutaListaFechamentos');\n    if (!alvo) return;\n    if (!itens || !itens.length) { alvo.innerHTML = '<div class=\"conduta-vazio\">Nenhuma competência fechada ainda.</div>'; return; }\n    var linhas = itens.map(function (f) {\n      return '<tr><td>' + escapeHtml_(f.competencia) + '</td><td>' + f.ico + '</td>' +\n        '<td><span class=\"conduta-status-pill\" style=\"background:' + tplConduta_corFarol_(f.farol) + ';color:#fff\">' + escapeHtml_(f.farol) + '</span></td>' +\n        '<td>' + escapeHtml_(f.fechadoEm || '') + '</td>' +\n        '<td><button type=\"button\" class=\"conduta-btn\" onclick=\"tplConduta_verRelatorio_(\\'' + f.competencia + '\\')\">Ver relatório</button> ' +\n        (tplConduta_podeGerir_() ? '<button type=\"button\" class=\"conduta-btn cinza\" onclick=\"tplConduta_regerarRelatorio_(\\'' + f.competencia + '\\')\">Gerar de novo</button>' : '—') + '</td></tr>';\n    }).join('');\n    alvo.innerHTML = '<table class=\"conduta-tabela\"><thead><tr><th>Competência</th><th>ICO</th><th>Farol</th><th>Fechado em</th><th>Relatório</th></tr></thead><tbody>' + linhas + '</tbody></table>';\n  });\n}\nfunction tplConduta_verRelatorio_(competencia) {\n  tplConduta_chamarApi_('apiObterRelatorio', { competencia: competencia }, function (res) {\n    if (!res || !res.html) return alert('Relatório ainda não foi gerado pra esta competência — clique em \"Gerar de novo\".');\n    var janela = window.open('', '_blank');\n    if (janela) { janela.document.write(res.html); janela.document.close(); }\n  });\n}\nfunction tplConduta_renderRelatoriosGerenciais_(){var b=document.getElementById('condutaTabBody');if(!b)return;b.innerHTML='<div class=\"conduta-card\"><h3>Relatório semanal para toda a equipe</h3><p>Apresenta o farol, as causas agregadas da perda de pontos, elogios, benefício coletivo, interpretação por IA e plano para a próxima semana.</p><div class=\"conduta-toolbar\"><input type=\"date\" id=\"cnd_rel_fim\" value=\"'+tplConduta_dataHoje_()+'\"><button class=\"conduta-btn verde\" onclick=\"tplConduta_gerarGerencial_(\\'SEMANAL\\')\">Gerar últimos 7 dias em A4</button><button class=\"conduta-btn cinza\" onclick=\"tplConduta_ativarSemanal_()\">Ativar geração todo domingo</button></div></div><div class=\"conduta-card\"><h3>Prestação de contas das missões</h3><p>Memória de cálculo por missão e executante para conferência do Financeiro e aprovação da Diretoria.</p><div class=\"conduta-toolbar\"><input type=\"month\" id=\"cnd_rel_comp\" value=\"'+tplConduta_competenciaAtual_()+'\"><button class=\"conduta-btn\" onclick=\"tplConduta_gerarGerencial_(\\'MISSOES\\')\">Gerar missões em A4</button></div></div><div id=\"cnd_rel_lista\" class=\"conduta-vazio\">Carregando relatórios publicados...</div>';tplConduta_listarGerenciais_();}\nfunction tplConduta_abrirHtmlGerencial_(html,w){if(w&&!w.closed){w.document.open();w.document.write(html);w.document.close();return;}var blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='relatorio-conduta.html';a.click();setTimeout(function(){URL.revokeObjectURL(url);},60000);alert('O navegador bloqueou a janela. O relatório foi disponibilizado para download.');}\n\nfunction tplConduta_gerarGerencial_(tipo){var api=tipo==='SEMANAL'?'apiGerarRelatorioSemanal':'apiGerarRelatorioMissoes',p=tipo==='SEMANAL'?{fim:getValue_('cnd_rel_fim')}:{competencia:getValue_('cnd_rel_comp')};if(CONDUTA_API_EM_VOO[api])return;var w=window.open('','_blank');if(w)w.document.write('<p>Gerando relatório…</p>');tplConduta_chamarApi_(api,p,function(r){tplConduta_abrirHtmlGerencial_(r.html,w);tplConduta_listarGerenciais_();},function(err){if(w&&!w.closed)w.close();alert('Não foi possível gerar: '+(err.message||err));});}\n\nfunction tplConduta_ativarSemanal_(){tplConduta_chamarApi_('apiAtivarRelatorioSemanalAutomatico',{},function(r){alert(r.mensagem||'Agendamento ativado.');});}\nfunction tplConduta_listarGerenciais_(){tplConduta_chamarApi_('apiListarRelatoriosGerenciais',{},function(rs){var e=document.getElementById('cnd_rel_lista');if(!e)return;if(!rs||!rs.length){e.textContent='Nenhum relatório publicado.';return;}e.innerHTML='<div style=\"overflow-x:auto\"><table class=\"conduta-tabela\"><thead><tr><th>Tipo</th><th>Período</th><th>Gerado em</th><th>Edição</th><th></th></tr></thead><tbody>'+rs.map(function(r){return '<tr><td>'+escapeHtml_(r.tipoLabel||r.tipo)+'</td><td>'+escapeHtml_(r.periodoLabel||r.periodo)+'</td><td>'+escapeHtml_(r.geradoEmLabel||r.geradoEm)+'</td><td>'+escapeHtml_(r.edicao||'—')+'</td><td><button class=\"conduta-btn cinza\" data-relatorio=\"'+escapeHtml_(r.id)+'\">Abrir</button></td></tr>';}).join('')+'</tbody></table></div>';e.querySelectorAll('[data-relatorio]').forEach(function(btn){btn.onclick=function(){tplConduta_abrirGerencial_(btn.getAttribute('data-relatorio'));};});});}\n\nfunction tplConduta_abrirGerencial_(id){var w=window.open('','_blank');if(w)w.document.write('<p>Carregando relatório…</p>');tplConduta_chamarApi_('apiObterRelatorioGerencial',{id:id},function(r){tplConduta_abrirHtmlGerencial_(r.html,w);},function(err){if(w&&!w.closed)w.close();alert('Não foi possível abrir: '+(err.message||err));});}\n\nfunction tplConduta_regerarRelatorio_(competencia) {\n  tplConduta_chamarApi_('apiGerarRelatorio', { competencia: competencia }, function (res) {\n    if (!res || !res.ok) return alert('Erro ao gerar relatório.');\n    var janela = window.open('', '_blank');\n    if (janela) { janela.document.write(res.html); janela.document.close(); }\n  });\n}\nfunction tplConduta_renderBiblioteca_(){\n var body=document.getElementById('condutaTabBody');if(!body)return;\n body.innerHTML='<div class=\"conduta-card\"><h3>Biblioteca Metrolabs</h3><p>Comece pelo manual do seu papel. Os três guias explicam os pilares por assunto, com exemplos e perguntas. Os PDFs originais estão disponíveis para conferir a redação oficial.</p><p>Os exemplos ajudam a entender; divergências entre documentos e regras configuradas devem ser encaminhadas à gestão antes de uma decisão.</p></div><div id=\"condutaBibliotecaLista\" class=\"conduta-vazio\">Carregando materiais...</div>';\n tplConduta_chamarApi_('apiListarBiblioteca',{},function(itens){\n  var lista=document.getElementById('condutaBibliotecaLista');if(!lista)return;\n  lista.className='';lista.innerHTML=(itens||[]).map(function(m){return '<article class=\"conduta-card\"><h3>'+escapeHtml_(m.titulo)+'</h3><p>'+escapeHtml_(m.descricao)+'</p><p style=\"font-size:12px\">'+(m.tipo==='ORIGINAL'?'Fonte original em PDF':'Manual/guia didático')+' · Edição '+escapeHtml_(m.versao)+'</p><button type=\"button\" class=\"conduta-btn\" data-material=\"'+escapeHtml_(m.id)+'\">Abrir para ler</button> <button type=\"button\" class=\"conduta-btn cinza\" data-baixar=\"'+escapeHtml_(m.id)+'\">Baixar</button></article>';}).join('');\n  lista.querySelectorAll('[data-material]').forEach(function(btn){btn.onclick=function(){tplConduta_abrirMaterial_(btn.getAttribute('data-material'));};});\n  lista.querySelectorAll('[data-baixar]').forEach(function(btn){btn.onclick=function(){tplConduta_abrirMaterial_(btn.getAttribute('data-baixar'),'',true);};});\n },function(err){var lista=document.getElementById('condutaBibliotecaLista');if(lista)lista.textContent='Não foi possível carregar a biblioteca: '+(err.message||err);});\n}\nfunction tplConduta_materialBlob_(m){\n if(m.base64){var raw=atob(m.base64),bytes=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type:m.mime});}\n return new Blob([m.html],{type:m.mime});\n}\nfunction tplConduta_baixarBlob_(blob,nome){var url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=nome;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},60000);}\nfunction tplConduta_abrirMaterial_(id,secao,baixar){\n var w=baixar?null:window.open('','_blank');if(w){w.opener=null;w.document.write('<p>Carregando material da biblioteca...</p>');}\n tplConduta_chamarApi_('apiObterMaterialBiblioteca',{id:id},function(m){\n  var blob=tplConduta_materialBlob_(m);\n  if(baixar||!w||w.closed){tplConduta_baixarBlob_(blob,m.arquivo);if(!baixar)alert('O navegador bloqueou a janela. O material foi disponibilizado para download.');return;}\n  if(m.html){w.document.open();w.document.write(m.html);w.document.close();if(secao){var alvo=w.document.getElementById(secao);if(alvo)alvo.scrollIntoView();}}\n  else {var url=URL.createObjectURL(blob);w.location.href=url;setTimeout(function(){URL.revokeObjectURL(url);},300000);}\n },function(err){if(w&&!w.closed)w.close();alert('Não foi possível abrir o material: '+(err.message||err));});\n}\nfunction tplConduta_competenciaAnterior_(){var d=new Date();d.setDate(1);d.setMonth(d.getMonth()-1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');}\nfunction tplConduta_previaHtml_(p){\n var r=p.resultado,esc=escapeHtml_,money=function(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});};\n var h='<h3>Prévia provisória de '+esc(tplConduta_compBR_(p.competencia))+'</h3><p><strong>'+esc(p.mensagem)+'</strong></p><p>ICO '+esc(String(r.ico))+' · Farol '+esc(r.farol)+' · Demérito '+esc(String(r.D))+' · Divisor '+esc(String(r.n))+'</p><p>Apuração feita agora; o cadastro de colaboradores ativos é o atual, pois o sistema não possui histórico datado de desligamentos. Esta prévia não autoriza pagamento e pode mudar após decisões.</p>';\n if(p.fechamentoCongelado)h+='<p><strong>Esta competência já foi congelada em '+esc(tplConduta_dataBR_(p.fechamentoData))+'. Os números desta prévia são uma consulta atual e não substituem o resultado histórico. Consulte o relatório do fechamento; divergências exigem ajuste administrativo formal.</strong></p>';\n h+='<h4>Ocorrências e defesas pendentes ('+p.pendencias.length+')</h4>';\n if(p.pendencias.length)h+='<div style=\"overflow-x:auto\"><table class=\"conduta-tabela\"><thead><tr><th>Ocorrência</th><th>Estado</th><th>Data do fato</th><th>Contestação até</th><th>Recurso até</th><th>Julgamento até</th></tr></thead><tbody>'+p.pendencias.map(function(o){return '<tr><td>'+esc(String(o.id))+'</td><td>'+esc(o.status)+'</td><td>'+esc(tplConduta_dataBR_(o.dataFato))+'</td><td>'+esc(tplConduta_dataBR_(o.prazoContestacao)||'—')+'</td><td>'+esc(tplConduta_dataBR_(o.prazoRecurso)||'—')+'</td><td>'+esc(tplConduta_dataBR_(o.prazoJulgamento)||'—')+'</td></tr>';}).join('')+'</tbody></table></div>';\n else h+='<p>Nenhuma defesa pendente identificada. O servidor verifica novamente antes de fechar.</p>';\n h+='<h4>Valores '+(r.sombra?'simulados':'provisórios')+' por colaborador</h4><div style=\"overflow-x:auto\"><table class=\"conduta-tabela\"><thead><tr><th>Colaborador</th><th>Bônus</th><th>Incentivo de missão</th><th>Bônus simulado</th><th>Incentivo simulado</th></tr></thead><tbody>'+(r.porColaborador||[]).map(function(c){return '<tr><td>'+esc(c.nome||String(c.colaboradorId))+'</td><td>'+money(c.valorBonus)+'</td><td>'+money(c.valorIncentivo)+'</td><td>'+money(c.valorSimuladoBonus)+'</td><td>'+money(c.valorSimuladoIncentivo)+'</td></tr>';}).join('')+'</tbody></table></div>';\n return h;\n}\nfunction tplConduta_consultarPrevia_(){\n var comp=getValue_('condutaPreviaComp'),alvo=document.getElementById('condutaPreviaResultado');if(!alvo)return;alvo.textContent='Consultando prévia e pendências...';\n tplConduta_chamarApi_('apiPreviaFechamento',{competencia:comp},function(p){\n  CONDUTA_ESTADO.previa=p;var a=document.getElementById('condutaPreviaResultado');if(!a)return;\n  a.innerHTML=tplConduta_previaHtml_(p)+'<div class=\"conduta-toolbar\"><button type=\"button\" class=\"conduta-btn cinza\" id=\"condutaImprimirPrevia\">Imprimir prévia</button>'+(p.podeFechar?'<button type=\"button\" class=\"conduta-btn verde\" id=\"condutaFecharPrevia\">Fechar competência conferida</button>':'<p>Fechamento definitivo indisponível: '+(p.fechamentoCongelado?'competência já congelada.':'aguarde as defesas/decisões e o encerramento do mês.')+'</p>')+'</div>';\n  document.getElementById('condutaImprimirPrevia').onclick=tplConduta_imprimirPrevia_;\n  var btn=document.getElementById('condutaFecharPrevia');if(btn)btn.onclick=function(){tplConduta_confirmarFechar_(p.competencia);};\n },function(err){var a=document.getElementById('condutaPreviaResultado');if(a)a.textContent='Falha na consulta: '+(err.message||err);});\n}\nfunction tplConduta_imprimirPrevia_(){\n var p=CONDUTA_ESTADO.previa;if(!p)return;var h='<!doctype html><html lang=\"pt-BR\"><meta charset=\"utf-8\"><title>Prévia Conduta '+escapeHtml_(p.competencia)+'</title><style>body{font:14px Arial;padding:24px;color:#17263c}table{border-collapse:collapse;width:100%;font-size:11px}td,th{border:1px solid #ccc;padding:6px;text-align:left}@media print{button{display:none}body{padding:0}}</style><body><p>Metrolabs · Conferência restrita à gestão · Emitida em '+escapeHtml_(new Date().toLocaleString('pt-BR'))+'</p>'+tplConduta_previaHtml_(p)+'<button onclick=\"window.print()\">Imprimir / salvar como PDF</button></body></html>';\n var w=window.open('','_blank');if(w){w.opener=null;w.document.write(h);w.document.close();}else tplConduta_baixarBlob_(new Blob([h],{type:'text/html;charset=utf-8'}),'previa-conduta-'+p.competencia+'.html');\n}\n\n</script>";
function Conduta_obterConteudoModulo(){return CONDUTA_CONTEUDO_MODULO;}
